cypress_script:
describe('Contact Us Form', () => {
  it('should submit the contact form successfully', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="name"]').type('John Doe');
    cy.get('input[name="email"]').type('john.doe@example.com');
    cy.get('input[name="subject"]').type('Feedback');
    cy.get('textarea#message').type('This is a test message.');
    cy.get('input[name="submit"]').click();
    cy.url().should('eq', 'https://automationexercise.com/contact_us');
  });

  it('should not submit the contact form with empty fields', () => {
    cy.visit('https://automationexercise.com/contact_us');
    cy.get('input[name="submit"]').click();
    cy.url().should('eq', 'https://automationexercise.com/contact_us');
  });
});

playwright_script:
test.describe('Contact Us Form', () => {
  test('should submit the contact form successfully', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.fill('input[name="name"]', 'John Doe');
    await page.fill('input[name="email"]', 'john.doe@example.com');
    await page.fill('input[name="subject"]', 'Feedback');
    await page.fill('textarea#message', 'This is a test message.');
    await page.click('input[name="submit"]');
    await page.waitForURL('https://automationexercise.com/contact_us');
  });

  test('should not submit the contact form with empty fields', async ({ page }) => {
    await page.goto('https://automationexercise.com/contact_us');
    await page.click('input[name="submit"]');
    await page.waitForURL('https://automationexercise.com/contact_us');
  });
});
